    (82, 'Paco Rabanne Phantom', 'Top: Lavender, Lemon Zest, Amalfi Lemon. Heart: Lavender, Apple, Smoke. Base: Vanilla, Lavender, Vetiver.', 'A futuristic aromatic fragrance born from the clash between luxury craftmanship and new tech.', '100 ml', 30, 'paco_rabanne_phantom.webp', 13800.00, 0, 1),
