    (85, 'Afnan Modest Une', 'Top: Pepper, Lavender, Mint, Citrus. Heart: Eucalyptus, Frankincense, Vetiver. Base: Cedarwood, Musk.', 'An aromatic, spicy, and woody powerhouse of freshness.', '100 ml', 15, 'afnan_modest_une.jpg', 4560.00, 0, 1),
    (86, 'Afnan 9AM Dive', 'Top: Mint, Lemon, Pink Pepper, Black Currant. Heart: Apple, Incense, Cedar. Base: Ginger, Sandalwood, Patchouli, Jasmine.', 'A versatile fresh blue fragrance suitable for day and night.', '100 ml', 40, 'afnan_9am_dive.webp', 3600.00, 0, 1),
