    (88, 'Jean Paul Gaultier Le Male', 'Top: Lavender, Mint, Cardamom, Bergamot. Heart: Cinnamon, Orange Blossom. Base: Vanilla, Tonka Bean, Amber, Sandalwood.', 'The iconic sailor torso bottle. A barbershop vanilla classic that redefined mens fragrance.', '125 ml', 35, 'jean_paul_gaultier_le_male.jpg', 11400.00, 0, 1),
    (89, 'Jean Paul Gaultier Scandal Pour Homme Le Parfum', 'Top: Geranium. Heart: Tonka Bean. Base: Sandalwood.', 'An intense, woody amber scent that commands attention.', '100 ml', 20, 'jean_paul_gaultier_scandal_pour_homme_le_parfum.jpg', 13800.00, 0, 1),
    (90, 'Jean Paul Gaultier Le Beau', 'Top: Bergamot. Heart: Coconut. Base: Tonka Bean.', 'A fresh, sweet, and seductive coconut wood fragrance.', '125 ml', 30, 'jean_paul_gaultier_le_beau.jpg', 12000.00, 0, 1),
    (91, 'Jean Paul Gaultier Classique', 'Top: Orange Blossom, Star Anise, Rose, Pear, Bergamot. Heart: Ylang-Ylang, Ginger, Orchid, Iris. Base: Vanilla, Amber, Musk.', 'A timeless symbol of seduction and extreme sensuality.', '100 ml', 15, 'jean_paul_gaultier_classique.jpg', 13200.00, 0, 1),
