    (93, 'Givenchy Pi', 'Top: Mandarin Orange, Tarragon, Rosemary, Basil. Heart: Anise, Neroli, Geranium. Base: Vanilla, Almond, Tonka Bean, Benzoin.', 'An excellent vanilla and almond fragrance for the intellectual explorer.', '100 ml', 18, 'givenchy_pi.jpg', 10800.00, 0, 1),
    (94, 'Givenchy Gentleman Eau de Parfum', 'Top: Black Pepper, Lavender, Bergamot. Heart: Orris, Cloves, Cinnamon. Base: Black Vanilla Husk, Tolu Balsam, Tonka Bean.', 'A sophisticated, spicy, and powdery iris fragrance for evenings.', '100 ml', 22, 'givenchy_gentleman_eau_de_parfum.jpg', 12600.00, 0, 1),
    (95, 'Givenchy Xeryus Rouge', 'Top: Cactus, Kumquat, Tarragon. Heart: Pimento, African Geranium. Base: Sandalwood, Cedar, White Musk.', 'A passionate, fiery red classic from 1995.', '100 ml', 10, 'givenchy_xeryus_rouge.jpg', 11400.00, 0, 1),
